<?php require_once __DIR__ . '/lib/accounts.php'; verify_csrf(); if ($_SERVER['REQUEST_METHOD'] !== 'POST') redirect('/login.php'); $login = strtolower(trim($_POST['login'] ?? '')); if (!rate_limit('login-ip', 10, 900) || !rate_limit_for('login-account', $login, 5, 900)) { flash('error', 'Muitas tentativas. Aguarde alguns minutos.'); redirect('/login.php'); } $user = authenticate($login, $_POST['password'] ?? ''); if (!$user) { flash('error', 'Credenciais inválidas.'); redirect('/login.php'); } login_user($user); record_audit('login', $user['id'], $user['id']); redirect($user['role'] === 'admin' ? '/admin/index.php' : '/cliente.php');
